        { domain: "Economics", skillId: "economics", cognitiveLevel: "Macroeconomic Tradeoff", stimulus: `<p>A central bank raises interest rates to slow inflation.</p>${table([["Likely channel", "Effect"], ["Borrowing cost", "increases"], ["Consumer demand", "may decrease"], ["Inflation pressure", "may slow"]])}`, question: "Which tradeoff should be considered?", correct: "Inflation may slow, but borrowing and growth may also weaken.", distractors: ["Loans become free.", "Inflation must rise immediately.", "Trade disappears when rates change."], explanation: "Higher rates can reduce demand but also slow activity.", itemPurpose: "Analyze policy tradeoffs.", misconception: "Student sees only the intended benefit.", stimulusType: "economics table", evidenceDemand: "tradeoff analysis" },
        { domain: "Civics", skillId: "source-analysis", cognitiveLevel: "Rights and Oversight", stimulus: `<p>A national security policy collects broad location data. Supporters cite threat prevention; critics cite privacy risks and weak oversight.</p>`, question: "Which evaluation question is strongest?", correct: "Are safety benefits proportional to privacy costs, and what oversight prevents misuse?", distractors: ["Can rights be ignored if officials claim safety?", "Does location data control weather?", "Are popular policies automatically constitutional?"], explanation: "Civics reasoning weighs security, rights, proportionality, and accountability.", itemPurpose: "Evaluate civic-policy tradeoffs.", misconception: "Student treats one public goal as overriding all constraints.", stimulusType: "policy scenario", evidenceDemand: "rights-policy evaluation" },
        { domain: "Geography", skillId: "source-analysis", cognitiveLevel: "Spatial Inequality", stimulus: `<p>Map layers show heat islands overlapping with low tree cover, older housing, and lower-income districts.</p>`, question: "Which inference is best supported?", correct: "Environmental burden is spatially unequal and linked with infrastructure patterns.", distractors: ["Heat is evenly distributed.", "Income causes sunlight directly.", "Trees increase heat intensity."], explanation: "Layered geography data support unequal exposure, not direct single-cause certainty.", itemPurpose: "Interpret geographic data layers.", misconception: "Student confuses spatial association with direct causation.", stimulusType: "map-layer scenario", evidenceDemand: "spatial pattern reasoning" }
